"""Semantic icon recipes. Keep each concept's defining structure visible at 96px."""
from drawing import *

ICONS=[]


def add(category,slug,name,body,description,tags=''):
    ICONS.append(dict(category=category,id=slug,name=name,body=body,description=description,
                      tags=sorted(set((tags+' '+slug.replace('-',' ')).split()))))


def build_icons():
    ICONS.clear()
    compute(); networking(); storage(); data(); ai(); agents(); development(); delivery(); security(); observability(); architecture(); math_icons(); connectors()
    return ICONS


